import queue
import threading
from typing import Callable, Any


class QueueWorker:
    def __init__(self, work_queue: queue.Queue, callback: Callable[[Any], None]):
        self.queue = work_queue
        self.callback = callback
        self.thread = None
        self.running = False

    def start(self) -> None:
        if self.running:
            return
        self.running = True
        self.thread = threading.Thread(target=self._process_queue, daemon=False)
        self.thread.start()

    def stop(self) -> None:
        self.running = False
        if self.thread:
            self.thread.join()

    def _process_queue(self) -> None:
        while self.running:
            try:
                item = self.queue.get(timeout=0.1)
                self.callback(item)
                self.queue.task_done()
            except queue.Empty:
                continue


if __name__ == "__main__":
    def handle_item(item: Any) -> None:
        print(f"Processed: {item}")

    q = queue.Queue()
    worker = QueueWorker(q, handle_item)
    worker.start()

    for i in range(5):
        q.put(i)

    q.join()
    worker.stop()
